import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * UC-002: View Veterinarians.
 */
class UC002ViewVeterinariansTest extends PetClinicTestBase {

    /** Seed rows in V2__seed_reference_data.sql, sorted by last name then first name. */
    private static final int SEEDED_VET_COUNT = 6;

    @Autowired
    private DSLContext dsl;

    @Test
    @UseCase(id = "UC-002")
    void veterinariansGridShowsAllSeededVets() {
        navigate(VeterinariansView.class);

        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
                "Expected exactly one veterinarians grid");
        assertEquals(SEEDED_VET_COUNT, test(grid).size(), "Expected one row per seeded veterinarian");
    }

    @Test
    @UseCase(id = "UC-002")
    void vetWithoutSpecialtiesShowsNone() {
        navigate(VeterinariansView.class);

        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
                "Expected exactly one veterinarians grid");
        // Row 0 is James Carter, who holds no specialties in the seed data.
        assertEquals("James", test(grid).getCellText(0, 0));
        assertEquals("Carter", test(grid).getCellText(0, 1));
        assertEquals("none", test(grid).getCellText(0, 2));
    }

    @Test
    @UseCase(id = "UC-002", businessRules = "BR-002")
    void specialtiesAreListedAlphabeticallyAndCommaSeparated() {
        navigate(VeterinariansView.class);

        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
                "Expected exactly one veterinarians grid");
        // Row 1 is Linda Douglas, seeded with surgery and dentistry.
        assertEquals("Douglas", test(grid).getCellText(1, 1));
        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
    }

    @Test
    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
    void emptyClinicRendersGridWithoutRows() {
        dsl.deleteFrom(VET_SPECIALTIES).execute();
        dsl.deleteFrom(VETS).execute();

        navigate(VeterinariansView.class);

        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
                "Expected the veterinarians grid to render without any vets");
        assertEquals(0, test(grid).size(), "Expected no rows when no veterinarian is registered");
    }

    @Test
    @UseCase(id = "UC-002", businessRules = "BR-003")
    void veterinariansViewIsReachableWithoutLogin() {
        // No authentication is performed, covering BR-003 (Anonymous Access).
        assertDoesNotThrow(() -> navigate(VeterinariansView.class),
                "Expected the veterinarians route to resolve without authentication");
    }
}
